import fs from 'node:fs/promises';
import {randomBytes} from 'node:crypto';
import {loadWorld} from './load-world.mjs';
import {DeepSeekClient} from './deepseek-client.mjs';
import {wildlifeFoundation} from '../world/design/wildlife-foundation.mjs';
import {wildlifeLoreSchema,wildlifeLoreIssues,validateWildlifeLore,auditWildlifeLore,contentHash,sampleRows} from './wildlife-content.mjs';
const world=await loadWorld(),bones=wildlifeFoundation(),runId=String(Date.now()),root=`world/drafts/wildlife/${runId}`;
await fs.mkdir(root,{recursive:true});const reviewSeeds=Array.from({length:Math.ceil(bones.monsters.length/50)},()=>randomBytes(4).readUInt32LE());
const generatorSources=await Promise.all(['tools/draft-wildlife.mjs','tools/wildlife-content.mjs','world/design/wildlife-foundation.mjs'].map(async file=>({file,source:await fs.readFile(file,'utf8')})));
const source={runId,sourceWorldHash:contentHash(world),boneHash:contentHash(bones),generatorHash:contentHash(generatorSources),reviewSeeds,bones};
await fs.writeFile(`${root}/source.json`,JSON.stringify(source,null,2));await fs.writeFile(`${root}/generator-sources.json`,JSON.stringify(generatorSources,null,2));
const client=new DeepSeekClient({budgetYuan:20}),rows=[],failures=[];
async function one(bone,index){
    let feedback=null;
    for(let attempt=1;attempt<=3;attempt++)try{
        const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
        const start=time(bone.wildlife.activeHours[0]),end=time(bone.wildlife.activeHours[1]),schema=structuredClone(wildlifeLoreSchema);
        schema.properties.id.const=bone.id;schema.properties.habits.pattern=`${start}[\\s\\S]*${end}`;
        const habitat=bones.rules.habitats.find(h=>h.id===bone.wildlife.habitat),input={bone,habitat,
            dailyActivity:`${start}至${bone.wildlife.activeHours[0]>bone.wildlife.activeHours[1]?'次日':''}${end}，其他时段休息；habits必须原样写出两个时间，不能重新换算为相反昼夜`,
            drops:bone.drops.map(d=>({...d,catalog:world.items.find(i=>i.id===d.item)})),food:bone.tamingRule?.food.map(f=>world.items.find(i=>i.id===f.item).name),feedback,
            constraints:['distinction是已经确认的习性或能力，folklore的误解不能否定它。火喉穴狸的热气确实能烘干穴口湿草，但不能点火或暖屋。',
                '取材每份的重量、保存期限和成品状态按drops.catalog.use与storage。刮净生皮仍湿润、未鞣制，不能在20分钟内宣称已经阴干；剖净鲜鱼去头去内脏并剔脊骨，剩余小刺仍在。',
                '刀具和一份250毫升清水已经登记为实际取材耗材。观察残余标本不新增商品或奖励。',
                '微小昆虫引起的是短暂干扰，不编造误工半日、重伤或整屋毁坏。',
                '所有行为都遵守dailyActivity。其他时段只休息，threat和folklore也不能额外编夜行或例外。',
                'materials有商品时只讲实际材料与处理保存，不列“其余不增加肉毒药金属”。没有商品时讲留下的爪痕、蜕壳、落羽等生态线索及记录方法，不写无掉落、不加工、不食用、不作商品、登记清水等操作保证。voice只写实际声音动作，不写无语言或不能说话。']};
        await fs.writeFile(`${root}/input-${index}-${attempt}.json`,JSON.stringify(input,null,2));
        const response=await client.generate({temperature:.45,max_tokens:2200,tools:[{type:'function',function:{name:'submit_species',description:'提交一个原创物种的图鉴文字，仅补指定七字段。',parameters:schema}}],tool_choice:{type:'function',function:{name:'submit_species'}},messages:[
            {role:'system',content:`写中文中世纪剑与魔法世界的野外图鉴。数值与生物骨架是既定事实，不能改等级、作息、食性、群居、材料和驯服。只输出id、appearance、habits、threat、materials、folklore、voice，严格遵守各字段长度。编号只用于id，其余用给定中文名称。appearance写distinction所述可辨特征及具体观察动作；habits按activeHours写晨昏/昼夜活动、觅食与巢穴，注意跨午夜时段，并将群居数量写清楚。threat写对居民具体造成的损失或干扰及避免接触的方法，微小动物的风险须与体型相称。materials在drops有商品时描述该商品的实际取材工序与保存：生皮用刀刮净并用清水处理，鱼用刀剖净；drops为空时只描述足迹、粪痕、蜕壳或啃痕的观察与辨认。所有限制只用于你检查事实，成文只呈现具体观察，不解释系统权限或未获商品。folklore写一则当地流传的具体误解及能验证的实际习性差别。voice只描述声音节拍或肢体表达。每种有自己的观察细节，避免开头句式相同与通用结尾。`},
            {role:'user',content:`字数按中文字符计，必须分别达到：appearance 85–115字；habits 120–150字；threat 80–105字；materials 60–85字；folklore 95–125字；voice 45–65字。不能每字段只写一句，每段应有可观察细节和相应作用。每字段自行检查长度后再提交；字数不足会整批拒绝。事实与上次校验错误如下：${JSON.stringify(input)}`}]},`wildlife-${runId}-${index}-${attempt}`);
        const calls=response.choices?.[0]?.message?.tool_calls??[],raw=calls[0]?.function?.arguments??response.choices?.[0]?.message?.content;
        await fs.writeFile(`${root}/attempt-${index}-${attempt}.json`,JSON.stringify({raw,calls,finishReason:response.choices?.[0]?.finish_reason},null,2));
        if(calls.length!==1||calls[0].function.name!=='submit_species')throw new Error('必须且只能提交一次指定图鉴工具');
        const row=JSON.parse(raw);if(!validateWildlifeLore(row))throw new Error(JSON.stringify(validateWildlifeLore.errors));
        if(!new RegExp(schema.properties.habits.pattern).test(row.habits))throw new Error('habits必须按顺序写出dailyActivity的两个时刻');
        const errors=wildlifeLoreIssues(row,bone);if(errors.length)throw new Error(errors.join('；'));
        rows.push(row);console.log(`物种 ${index+1}/${bones.monsters.length} 结构完成`);return true;
    }catch(error){feedback=error.message;failures.push({id:bone.id,attempt,error:feedback});console.log(`物种${index}第${attempt}次失败，原输出保留`);}
    return false;
}
for(let i=0;i<bones.monsters.length;i+=6){const results=await Promise.all(bones.monsters.slice(i,i+6).map((b,n)=>one(b,i+n)));if(results.some(ok=>!ok))break;}
rows.sort((a,b)=>bones.monsters.findIndex(m=>m.id===a.id)-bones.monsters.findIndex(m=>m.id===b.id));
const audit=auditWildlifeLore(rows,bones);await fs.writeFile(`${root}/lore.json`,JSON.stringify(rows,null,2));await fs.writeFile(`${root}/audit.json`,JSON.stringify(audit,null,2));
for(let batch=0;batch<reviewSeeds.length;batch++){
    const slice=rows.slice(batch*50,batch*50+50),review={runId,batch,seed:reviewSeeds[batch],boneHash:source.boneHash,loreHash:contentHash(rows),approved:false,
        scope:'待人工随机精读；任何一项不合格整批重做，不逐项拼接修补',sample:sampleRows(slice,reviewSeeds[batch]).map(row=>({id:row.id,hash:contentHash(row),scores:null,notes:null}))};
    await fs.writeFile(`docs/内容审查/物种-${runId}-批${batch}.json`,JSON.stringify(review,null,2));
}
const report={runId,root,planned:bones.monsters.length,structured:rows.length,audit,failures,costUpperYuan:client.spent,manualApproved:false};
await fs.writeFile(`docs/测试报告/物种起草-${runId}.json`,JSON.stringify(report,null,2));
if(!audit.ok)await fs.writeFile(`docs/内容审查/物种待处理-${runId}.json`,JSON.stringify(report,null,2));
console.log(JSON.stringify({runId,structured:rows.length,autoPassed:audit.ok,costUpperYuan:client.spent,manualApproved:false}));if(!audit.ok)process.exitCode=1;

import Ajv from 'ajv';
import {contentHash,sampleRows} from './economy-content.mjs';
import {withWildlife,wildlifeFoundation} from '../world/design/wildlife-foundation.mjs';
import {validateWorld} from './validate-world.mjs';
export {contentHash,sampleRows};
const field=(minLength,maxLength)=>({type:'string',minLength,maxLength});
export const wildlifeLoreSchema={type:'object',additionalProperties:false,required:['id','appearance','habits','threat','materials','folklore','voice'],properties:{
    id:field(1,100),appearance:field(65,135),habits:field(90,180),threat:field(55,125),materials:field(40,100),folklore:field(65,145),voice:field(30,85)}};
const ajv=new Ajv({allErrors:true,strict:true});export const validateWildlifeLore=ajv.compile(wildlifeLoreSchema);
export const corpus=row=>['appearance','habits','threat','materials','folklore','voice'].map(key=>row[key]??'').join('');
export function wildlifeLoreIssues(row,bone){
    const errors=[];if(!validateWildlifeLore(row))errors.push(JSON.stringify(validateWildlifeLore.errors));
    const text=corpus(row);if(/主持人|提示词|玩家不能|不要让|禁止|系统要求|JSON|schema|编号|生成器/.test(text))errors.push('图鉴泄漏开发或主持规则');
    if(/塑料|电动|电池|汽车|现代科技|原地重生|无限刷新/.test(text))errors.push('现代技术或刷新保证');
    for(const key of ['appearance','habits','threat','materials','folklore','voice']){
        const phrase=row[key]?.match(/无掉落|登记清水|不增肉|不加工|不作商品|无法加工|不可加工|不能加工|无语言/)?.[0];
        if(phrase)errors.push(`${key}含开发保证句“${phrase}”：改写为可观察的行为或痕迹，不写掉落、加工或语言能力的操作限制`);
    }
    if(!bone||row.id!==bone.id)errors.push('物种编号不符');
    if(bone?.intelligence===0&&/[“「][^”」]*[我你您他她谁请要让别是的][^”」]*[”」]/.test(row.voice))errors.push('无灵智野兽被赋予人类台词');
    if(bone?.drops.length===0&&/可(?:剥取|采集|提炼|得到|获取|收获)/.test(row.materials))errors.push('没有登记掉落的物种被添加可用材料');
    if(bone?.drops.some(d=>d.item==='item_rawhide')&&/阴干|风干|晒干/.test(row.materials))errors.push('实际20分钟取材只产湿生皮，不得宣称已经干燥');
    if(bone?.id==='monster_ember_throat_civet'&&/(?:连|不|无法|不能)[^。；]{0,12}湿草[^。；]{0,8}(?:烘不干|不干)|(?:不能|无法)[^。；]{0,8}烘干[^。；]{0,5}湿草/.test(corpus(row)))errors.push('火喉穴狸既定能烘干穴口湿草，民间纠误不能否定该能力');
    return errors;
}
export function auditWildlifeLore(rows,bones){
    const errors=[],map=new Map(bones.monsters.map(b=>[b.id,b]));
    if(rows.length!==bones.monsters.length||new Set(rows.map(r=>r.id)).size!==rows.length)errors.push('物种遗漏或重复');
    for(const row of rows)errors.push(...wildlifeLoreIssues(row,map.get(row.id)).map(message=>({id:row.id,message})));
    const sets=rows.map(row=>{const text=corpus(row).replace(/[^\p{L}]/gu,'');return new Set(Array.from({length:text.length-1},(_,i)=>text.slice(i,i+2)));});
    let maximumSimilarity=0;
    for(let i=0;i<sets.length;i++)for(let j=0;j<i;j++){
        const common=[...sets[i]].filter(g=>sets[j].has(g)).length,score=common/(sets[i].size+sets[j].size-common||1);maximumSimilarity=Math.max(maximumSimilarity,score);
        if(score>=.35)errors.push({id:rows[i].id,other:rows[j].id,similarity:score});
    }
    return{ok:errors.length===0,errors,maximumSimilarity};
}
export function assembleWildlife(world,bones,rows){
    const map=new Map(rows.map(r=>[r.id,r])),audit=auditWildlifeLore(rows,bones);if(!audit.ok)throw new Error(JSON.stringify(audit.errors));
    return withWildlife(world,bones.monsters.map(b=>({...b,...map.get(b.id)})));
}
export function verifyWildlifePublication(world,source,rows,reviews){
    if(source.sourceWorldHash!==contentHash(world)||source.boneHash!==contentHash(wildlifeFoundation()))throw new Error('世界或物种骨架已变化，拒绝旧证明');
    if(!Array.isArray(source.reviewSeeds)||source.reviewSeeds.length!==Math.ceil(rows.length/50))throw new Error('缺起草前随机抽样种子');
    for(let batch=0;batch<source.reviewSeeds.length;batch++){
        const review=reviews.find(r=>r.batch===batch),sample=sampleRows(rows.slice(batch*50,batch*50+50),source.reviewSeeds[batch]);
        if(!review?.approved||review.runId!==source.runId||review.seed!==source.reviewSeeds[batch]||review.boneHash!==source.boneHash||review.loreHash!==contentHash(rows)||review.sample.length!==sample.length)throw new Error('缺少匹配的人工批次审核');
        for(const row of sample){const read=review.sample.find(r=>r.id===row.id);
            if(!read||read.hash!==contentHash(row)||read.scores?.length!==6||read.scores.some(n=>!Number.isInteger(n)||n<3||n>5)||read.scores.reduce((a,b)=>a+b,0)/6<4||!read.notes?.trim())throw new Error(`人工样本不合格：${row.id}`);
        }
    }
    const candidate=assembleWildlife(world,source.bones,rows),validation=validateWorld(candidate);if(!validation.ok)throw new Error(validation.errors.join('\n'));return candidate;
}

