        Object.assign(find(name).wildlife,{population,capacity,recoveryPerWeek});
    return{monsters,rules:{version:1,trackMinutes:60,maximumPresent:6,corpseMinutes:2880,seasonRecovery:[1,1.2,0.8,0.25],
